WITH flags AS ( SELECT CASE WHEN $2 THEN NOT EXISTS ( SELECT 1 FROM email_message_labels ml JOIN email_labels l ON l.id = ml.label_id WHERE ml.message_id = m.id AND l.provider_label_id = $4 ) ELSE m.is_read END AS is_read, CASE WHEN $3 THEN EXISTS ( SELECT 1 FROM email_message_labels ml JOIN email_labels l ON l.id = ml.label_id WHERE ml.message_id = m.id AND l.provider_label_id = $5 ) ELSE m.is_starred END AS is_starred FROM email_messages m WHERE m.id = $1 ) UPDATE email_messages m SET is_read = flags.is_read, is_starred = flags.is_starred FROM flags WHERE m.id = $1 AND (m.is_read, m.is_starred) IS DISTINCT FROM (flags.is_read, flags.is_starred)
